fn rb_last(root: *const rb_root) -> *mut rb_node {
let mut n: *mut rb_node = unsafe { core::mem::zeroed() };
n = unsafe { (*root).rb_node };
if n.is_null() {
return core::ptr::null_mut::<rb_node>();
}
while !unsafe { (*n).rb_right }.is_null() {
n = unsafe { (*n).rb_right };
}
n
}

